#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ReciprocalArea; 11] = [
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareMeter),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareKilometer),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareDecimeter),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareCentimeter),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareMillimeter),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareMicrometer),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareMile),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareYard),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareFoot),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseUsSurveySquareFoot),
        ReciprocalArea::const_new(1234.5, ReciprocalAreaUnit::InverseSquareInch),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ReciprocalAreaUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ReciprocalArea::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ReciprocalAreaUnit::ALL {
            assert_eq!(
                ReciprocalArea::const_new(v, unit).as_base().to_bits(),
                ReciprocalArea::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ReciprocalArea::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ReciprocalArea::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ReciprocalAreaUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ReciprocalArea::from_base(0.0).auto_unit().unit,
        ReciprocalAreaUnit::InverseSquareMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "m⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "m⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareMeter
        ))
    );
    assert_eq!(
        "km⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareKilometer)
    );
    assert_eq!(
        format!("2.5 {}", "km⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareKilometer
        ))
    );
    assert_eq!(
        "dm⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareDecimeter)
    );
    assert_eq!(
        format!("2.5 {}", "dm⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareDecimeter
        ))
    );
    assert_eq!(
        "cm⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "cm⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareCentimeter
        ))
    );
    assert_eq!(
        "mm⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareMillimeter)
    );
    assert_eq!(
        format!("2.5 {}", "mm⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareMillimeter
        ))
    );
    assert_eq!(
        "µm⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareMicrometer)
    );
    assert_eq!(
        format!("2.5 {}", "µm⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareMicrometer
        ))
    );
    assert_eq!(
        "mi⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareMile)
    );
    assert_eq!(
        format!("2.5 {}", "mi⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareMile
        ))
    );
    assert_eq!(
        "yd⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareYard)
    );
    assert_eq!(
        format!("2.5 {}", "yd⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareYard
        ))
    );
    assert_eq!(
        "ft⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareFoot)
    );
    assert_eq!(
        format!("2.5 {}", "ft⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareFoot
        ))
    );
    assert_eq!(
        "ft⁻² (US)".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseUsSurveySquareFoot)
    );
    assert_eq!(
        format!("2.5 {}", "ft⁻² (US)").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseUsSurveySquareFoot
        ))
    );
    assert_eq!(
        "in⁻²".parse::<ReciprocalAreaUnit>(),
        Ok(ReciprocalAreaUnit::InverseSquareInch)
    );
    assert_eq!(
        format!("2.5 {}", "in⁻²").parse::<ReciprocalArea>(),
        Ok(ReciprocalArea::new(
            2.5,
            ReciprocalAreaUnit::InverseSquareInch
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ReciprocalArea>(),
        Err(ParseError::UnknownUnit)
    );
}

